-- Metadata/policy contract only; no blob bytes are uploaded by SQL. All fixtures roll back.
begin;
create function pg_temp.p_id(n integer) returns uuid language sql immutable as $$select ('f7000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.p_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.p_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected SQLSTATE %',state;end$$;
create function pg_temp.p_player(pts integer) returns jsonb language sql as $$select jsonb_build_object('jerseyNumber','00','name','Source player','starter',false,'captain',false,'didNotPlay',false,'secondsPlayed',10,'fieldGoals',jsonb_build_object('made',1,'attempted',1),'twoPoints',jsonb_build_object('made',case when pts=2 then 1 else 0 end,'attempted',case when pts=2 then 1 else 0 end),'threePoints',jsonb_build_object('made',case when pts=3 then 1 else 0 end,'attempted',case when pts=3 then 1 else 0 end),'freeThrows',jsonb_build_object('made',0,'attempted',0),'offensiveRebounds',0,'defensiveRebounds',0,'rebounds',0,'assists',0,'turnovers',0,'steals',0,'blocks',0,'foulsCommitted',0,'foulsReceived',null,'plusMinus',null,'efficiency',pts,'points',pts)$$;
create function pg_temp.p_command(n integer default 10,h text default repeat('a',64)) returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.p_id(n),'source',jsonb_build_object('id',pg_temp.p_id(n+1),'disputeId',pg_temp.p_id(3),'filename','Fixture.pdf','sha256',h,'byteSize',10,'pageCount',2,'parsed',jsonb_build_object('format','BASKETBALL_SITE','parserVersion','basketball-site-v1','competitionName',null,'gameNumber',null,'scheduledLocal','2026-05-13T20:30','durationSeconds',null,'venue','Fixture','warnings','[]'::jsonb,'teams',jsonb_build_array(jsonb_build_object('name','Home','abbreviation','H','score',2,'periodScores',null,'players',jsonb_build_array(pg_temp.p_player(2))),jsonb_build_object('name','Away','abbreviation','A','score',3,'periodScores',null,'players',jsonb_build_array(pg_temp.p_player(3)))))))$$;
grant execute on function pg_temp.p_id(integer),pg_temp.p_assert(boolean,text),pg_temp.p_error(text,text),pg_temp.p_player(integer),pg_temp.p_command(integer,text) to anon,authenticated,service_role;
delete from public.admin_access;
insert into auth.users(id) values(pg_temp.p_id(98)),(pg_temp.p_id(99));
insert into public.admin_access(user_id) values(pg_temp.p_id(98));
insert into public.championships(id,name) values(pg_temp.p_id(1),'G3 fixture');
insert into public.seasons(id,championship_id,year) values(pg_temp.p_id(2),pg_temp.p_id(1),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.p_id(3),pg_temp.p_id(2),'masculino','Adulto');
insert into public.teams(id,name) values(pg_temp.p_id(40),'PDF contextual team');
insert into public.registrations(id,dispute_id,team_id,name) values(pg_temp.p_id(41),pg_temp.p_id(3),pg_temp.p_id(40),'Home'),(pg_temp.p_id(42),pg_temp.p_id(3),pg_temp.p_id(40),'Away'),(pg_temp.p_id(43),pg_temp.p_id(3),pg_temp.p_id(40),'Other');
insert into public.games(id,dispute_id,home_registration_id,away_registration_id) values(pg_temp.p_id(44),pg_temp.p_id(3),pg_temp.p_id(41),pg_temp.p_id(42));
insert into public.persons(id,name) values(pg_temp.p_id(50),'Player home'),(pg_temp.p_id(51),'Player away'),(pg_temp.p_id(52),'Other player');
insert into private.athletes(person_id,sex) values(pg_temp.p_id(50),'male'),(pg_temp.p_id(51),'male'),(pg_temp.p_id(52),'female');
insert into public.roster_entries(id,registration_id,dispute_id,person_id,jersey) values(pg_temp.p_id(60),pg_temp.p_id(41),pg_temp.p_id(3),pg_temp.p_id(50),'12'),(pg_temp.p_id(61),pg_temp.p_id(42),pg_temp.p_id(3),pg_temp.p_id(51),'77'),(pg_temp.p_id(62),pg_temp.p_id(41),pg_temp.p_id(3),pg_temp.p_id(52),'23');
insert into public.championships(id,name) values(pg_temp.p_id(80),'Other root');
insert into public.seasons(id,championship_id,year) values(pg_temp.p_id(81),pg_temp.p_id(80),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.p_id(82),pg_temp.p_id(81),'masculino','Adulto');
create function pg_temp.p_review(n integer default 70) returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.p_id(n),'sourceId',pg_temp.p_id(11),'expectedVersion',0,'document',jsonb_build_object('disputeId',pg_temp.p_id(3),'gameId',pg_temp.p_id(44),'invertSides',false,'notes','','mappings',jsonb_build_array(jsonb_build_object('sourceSide',0,'sourceIndex',0,'rosterEntryId',pg_temp.p_id(60),'jersey','00'),jsonb_build_object('sourceSide',1,'sourceIndex',0,'rosterEntryId',pg_temp.p_id(61),'jersey','00'))))$$;
grant execute on function pg_temp.p_review(integer) to anon,authenticated,service_role;
set local role authenticated;
set local request.jwt.claim.sub='f7000000-0000-4000-8000-000000000098';
select public.prepare_pdf_source(pg_temp.p_command());
select pg_temp.p_error('select public.get_pdf_review(pg_temp.p_id(11))','PT409');
insert into storage.objects(bucket_id,name,metadata,owner_id) values('boxscore-sources','sources/'||pg_temp.p_id(11)::text||'.pdf','{"mimetype":"application/pdf","size":10}',pg_temp.p_id(98)::text);
select public.finish_pdf_source(jsonb_build_object('commandId',pg_temp.p_id(10),'sourceId',pg_temp.p_id(11)));
select pg_temp.p_assert((public.get_pdf_review(pg_temp.p_id(11))->>'version')::int=0,'unsaved initial review projected without insert');
select pg_temp.p_assert((select count(*) from public.pdf_reviews)=0,'reader creates no review rows');
select pg_temp.p_assert((public.save_pdf_review(pg_temp.p_review())->>'version')::int=1,'review saved');
select pg_temp.p_assert((public.save_pdf_review(pg_temp.p_review())->>'version')::int=1,'idempotent review replay');
select pg_temp.p_error($q$select public.save_pdf_review(jsonb_set(pg_temp.p_review(),'{document,notes}','"different"'))$q$,'PT409');
select pg_temp.p_error('select public.save_pdf_review(pg_temp.p_review(71))','PT409');
select pg_temp.p_error($q$select public.save_pdf_review(jsonb_set(jsonb_set(pg_temp.p_review(72),'{expectedVersion}','1'),'{document,mappings,0,rosterEntryId}',to_jsonb(pg_temp.p_id(61))))$q$,'PT400');
select pg_temp.p_error($q$select public.save_pdf_review(jsonb_set(jsonb_set(pg_temp.p_review(73),'{expectedVersion}','1'),'{document,mappings,0,rosterEntryId}',to_jsonb(pg_temp.p_id(62))))$q$,'PT400');
select pg_temp.p_error($q$select public.save_pdf_review(jsonb_set(jsonb_set(pg_temp.p_review(74),'{expectedVersion}','1'),'{document,mappings}','[]'))$q$,'PT400');
select pg_temp.p_assert((public.get_pdf_review(pg_temp.p_id(11))->>'version')::int=1,'invalid intent is atomic');
reset role;
select pg_temp.p_error($q$update public.games set away_registration_id=pg_temp.p_id(43) where id=pg_temp.p_id(44)$q$,'PT409');
set local role authenticated;
select public.save_pdf_review(jsonb_set(jsonb_set(jsonb_set(jsonb_set(pg_temp.p_review(75),'{expectedVersion}','1'),'{document,invertSides}','true'),'{document,mappings,0,rosterEntryId}',to_jsonb(pg_temp.p_id(61))),'{document,mappings,1,rosterEntryId}',to_jsonb(pg_temp.p_id(60))));
-- Explicit retargeting retains original bytes/hash and resets unresolved associations.
select public.save_pdf_review(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(pg_temp.p_review(76),'{expectedVersion}','2'),'{document,disputeId}',to_jsonb(pg_temp.p_id(82))),'{document,gameId}','null'),'{document,mappings,0,rosterEntryId}','null'),'{document,mappings,1,rosterEntryId}','null'));
select pg_temp.p_assert(public.get_pdf_review(pg_temp.p_id(11))->'document'->>'disputeId'=pg_temp.p_id(82)::text,'review moved to explicit target');
select pg_temp.p_assert(public.get_pdf_source(pg_temp.p_id(11))->>'sha256'=repeat('a',64),'file identity unchanged');
select pg_temp.p_assert(jsonb_array_length(public.list_pdf_sources(pg_temp.p_id(3))->'items')=0 and jsonb_array_length(public.list_pdf_sources(pg_temp.p_id(82))->'items')=1,'source resumes in current review context');
select pg_temp.p_error('insert into public.pdf_reviews(source_id) values(pg_temp.p_id(11))','42501');
set local request.jwt.claim.sub='f7000000-0000-4000-8000-000000000099';
select pg_temp.p_assert(public.get_pdf_review(pg_temp.p_id(11)) is null,'nonadmin review denied');
reset role;
select pg_temp.p_error($q$update public.disputes set gender='feminino' where id=pg_temp.p_id(82)$q$,'PT409');
update public.admin_access set enabled=false;
set local role authenticated;
set local request.jwt.claim.sub='f7000000-0000-4000-8000-000000000098';
select pg_temp.p_error('select public.save_pdf_review(pg_temp.p_review())','PT403');
set local role anon;
select pg_temp.p_error('select public.get_pdf_review(pg_temp.p_id(11))','42501');
set local role service_role;
select pg_temp.p_error('select public.get_pdf_review(pg_temp.p_id(11))','42501');
reset role;
rollback;
